@extends('layouts.app') @section('title',$l->group_name.' · '.$l->subject_name) @section('content')<div class="mb-3"><a href="{{route('journal.today',['date'=>$l->lesson_date])}}" class="text-decoration-none">← К занятиям</a><h1 class="h4 mt-2 mb-0">{{$l->subject_name}}</h1><div class="text-secondary">{{$l->group_name}} · {{date('d.m.Y',strtotime($l->lesson_date))}} · пара {{$l->lesson_number}}</div></div>@if(auth()->user()->canDo('grades.mark'))<div class="card mb-3"><div class="card-body"><form method="post" action="{{route('journal.content',$l->id)}}">@csrf<label class="form-label fw-semibold">Тема занятия</label><textarea class="form-control mb-2" name="topic" rows="2" placeholder="Что проходили">{{$l->topic}}</textarea><label class="form-label fw-semibold">Домашнее задание</label><textarea class="form-control mb-2" name="homework" rows="2" placeholder="Задание к следующему занятию">{{$l->homework}}</textarea><button class="btn btn-primary w-100">Сохранить тему и ДЗ</button></form></div></div>@elseif($l->topic||$l->homework)<div class="card mb-3"><div class="card-body">@if($l->topic)<div class="small text-secondary">Тема</div><div class="mb-2">{{$l->topic}}</div>@endif@if($l->homework)<div class="small text-secondary">Домашнее задание</div><div class="fw-semibold">{{$l->homework}}</div>@endif</div></div>@endif @if(auth()->user()->canDo('semester.view'))<a class="btn btn-outline-primary mb-3" href="{{route('semester.edit',[$l->study_group_id,$l->subject_id])}}">Итоги по предмету</a>@endif@if(auth()->user()->canDo('attendance.mark'))<button type="button" id="allPresent" class="btn btn-success w-100 mb-2">✓ Все присутствуют</button>@endif<div id="saveStatus" class="small text-secondary mb-2">Изменения сохраняются автоматически</div><div class="card overflow-hidden"><div class="list-group list-group-flush">@foreach($students as $s)<div class="list-group-item p-3 student-row" data-student="{{$s->id}}"><div class="fw-semibold mb-2">{{$loop->iteration}}. {{$s->last_name}} {{$s->first_name}} {{$s->middle_name}}</div><div class="d-flex flex-wrap gap-2 align-items-center">@if(auth()->user()->canDo('attendance.mark'))<div class="btn-group attendance">@foreach(['present'=>'✓','absent'=>'Н','late'=>'О','excused'=>'У','sick'=>'Б'] as $v=>$n)<button type="button" class="btn btn-sm {{$s->attendance_status===$v?'btn-primary':'btn-outline-secondary'}}" data-value="{{$v}}">{{$n}}</button>@endforeach</div>@else<span class="badge text-bg-light">{{$s->attendance_status?:'нет отметки'}}</span>@endif @if(auth()->user()->canDo('grades.mark')&&!auth()->user()->hasRole('starosta'))<div class="btn-group grades ms-auto">@foreach(['2','3','4','5'] as $v)<button type="button" class="btn btn-sm btn-outline-success" data-value="{{$v}}">{{$v}}</button>@endforeach</div>@endif</div>@if(isset($grades[$s->id]))<div class="small mt-2">Оценки: @foreach($grades[$s->id] as $g)<span class="badge text-bg-success">{{$g->value}}</span> @endforeach</div>@endif</div>@endforeach</div></div>@endsection
@push('scripts')<script>$(function(){const csrf=$('meta[name=csrf-token]').attr('content');const Q='chist-attendance-queue';function queue(){try{return JSON.parse(localStorage.getItem(Q)||'[]')}catch(e){return[]}}function badge(){let n=queue().length;window.dispatchEvent(new CustomEvent('chist-queue',{detail:n}))}function enqueue(url,data){let q=queue();q.push({url,data});localStorage.setItem(Q,JSON.stringify(q));badge();state('Офлайн: сохранено на телефоне ⏳')}async function flush(){if(!navigator.onLine)return;let q=queue(),left=[];for(let x of q){try{let body=new URLSearchParams(x.data);let r=await fetch(x.url,{method:'POST',headers:{'X-CSRF-TOKEN':csrf,'Accept':'application/json','Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body});if(!r.ok)left.push(x)}catch(e){left.push(x)}}localStorage.setItem(Q,JSON.stringify(left));badge();if(q.length&&!left.length)state('Офлайн-отметки синхронизированы ✓')}window.addEventListener('online',flush);badge();flush();function state(t){$('#saveStatus').text(t)}$('#allPresent').on('click',function(){if(!confirm('Отметить всех студентов присутствующими?'))return;state('Сохраняю перекличку…');$.post('{{route('journal.attendance.all',$l->id)}}',{_token:csrf}).done(()=>{state('Все присутствующие сохранены ✓');$('.attendance button[data-value=present]').each(function(){let b=$(this);b.siblings().removeClass('btn-primary').addClass('btn-outline-secondary');b.removeClass('btn-outline-secondary').addClass('btn-primary')})}).fail(()=>state('Ошибка сохранения'))});$('.attendance button').on('click',function(){let b=$(this),row=b.closest('.student-row');state('Сохраняю…');let data={_token:csrf,student_id:row.data('student'),status:b.data('value')};if(!navigator.onLine){enqueue('{{route('journal.attendance',$l->id)}}',data);b.siblings().removeClass('btn-primary').addClass('btn-outline-secondary');b.removeClass('btn-outline-secondary').addClass('btn-primary');return}$.post('{{route('journal.attendance',$l->id)}}',data).done(()=>{b.siblings().removeClass('btn-primary').addClass('btn-outline-secondary');b.removeClass('btn-outline-secondary').addClass('btn-primary');state('Сохранено ✓')}).fail(()=>{enqueue('{{route('journal.attendance',$l->id)}}',data);b.siblings().removeClass('btn-primary').addClass('btn-outline-secondary');b.removeClass('btn-outline-secondary').addClass('btn-primary')})});$('.grades button').on('click',function(){let b=$(this),row=b.closest('.student-row');state('Сохраняю оценку…');$.post('{{route('journal.grade',$l->id)}}',{_token:csrf,student_id:row.data('student'),value:b.data('value')}).done(()=>{state('Оценка '+b.data('value')+' сохранена ✓');location.reload()}).fail(()=>state('Ошибка сохранения оценки'))});});</script>@endpush